import ghidra.app.script.GhidraScript;import ghidra.app.emulator.EmulatorHelper;import java.io.*;
public class ZNov04UnitRayOracle extends GhidraScript{static final long U=0x5e30c8L,S=0x7fff0000L,RET=0x12345000L;void put(EmulatorHelper e,long a,int n,long v)throws Exception{e.writeMemoryValue(toAddr(a),n,v);}public void run()throws Exception{try(PrintWriter out=new PrintWriter(getScriptArgs()[0])){for(int n=0;n<1024;n++){EmulatorHelper e=new EmulatorHelper(currentProgram);try{e.writeMemory(toAddr(U),new byte[384]);put(e,U+44,2,500+n%17);put(e,U+46,2,600+n%11);put(e,U+192+44,2,500+(n%13-6)*30);put(e,U+192+46,2,600+(n/13%11-5)*30);put(e,U+0x7c,1,new int[]{0,1,2,15}[n%4]);put(e,U+192+0x7c,1,new int[]{0,1,2,16}[n/4%4]);int acell=n*31%16384,bcell=(n*47+3)%16384;put(e,U+0x10,4,acell);put(e,U+192+0x10,4,bcell);byte[]t=new byte[16384];for(int y=0;y<128;y++){t[y*128+34]=19;t[y*128+35]=24;}for(int x=0;x<128;x++)t[36*128+x]=n%3==0?(byte)17:0;t[acell]=(byte)new int[]{0,17,19,24,35,38,66,127}[n/16%8];t[bcell]=(byte)new int[]{0,17,19,24,35,38,66,127}[n/128%8];e.writeMemory(toAddr(0x58aaaa),t);put(e,0x4948d4,4,n%2==0?0x499ab0:0x49a140);e.writeRegister("ESP",S);put(e,S,4,RET);e.writeRegister("ECX",0);e.writeRegister("EDX",1);e.setBreakpoint(toAddr(RET));if(!e.run(toAddr(0x432320),null,monitor))throw new Exception(e.getLastError());if(e.readRegister("EIP").longValue()!=RET)throw new Exception("stop");out.println("{\"scenario\":"+n+",\"visible\":"+((e.readRegister("EAX").intValue()&255)==0?1:0)+"}");}finally{e.dispose();}}}}}
